     * `day_backfilled` flag (flags are not peelable events; revoke the
     * backfill itself via `revoke_event`), or nothing was logged.
     * `DayState.revocable` reports, per task, whether this call would
     * succeed.
     */
    fun `revokeTask`(`date`: kotlin.String, `kind`: RevocableTask, `now`: LocalInstant): LogResult
    
    /**
     * `now` stamps the challenge config-LWW slot (the book lives on the
     * challenge row — docs/PHASE2.md).
     */
    fun `setCurrentBook`(`title`: kotlin.String, `now`: LocalInstant)
    
    /**
     * Edit the day cutoff (minutes past local midnight the day rolls over).
     * Unlike the other setters, the cutoff decides which DAY a live log lands
     * on, so it is event-sourced and FORWARD-ONLY: this records a
     * `cutoff_changed` event stamped at `now`, and the projection attributes
     * each event under the cutoff that was live when it was logged. Already-
     * logged days keep the boundary they were lived under; only later logs use
     * the new cutoff — resolving the hazard the `set_start_date` note warns of
     * (a naive setter would move events to different days). The DB column stays
     * the initial cutoff; `active_challenge` surfaces the current one.
     */
    fun `setDayCutoff`(`dayCutoffMinutes`: kotlin.UInt, `now`: LocalInstant)
    
    /**
     * Display-only config; safe to edit mid-challenge. `now` stamps the
     * challenge config-LWW slot (docs/PHASE2.md).
     */
    fun `setDietDescription`(`desc`: kotlin.String, `now`: LocalInstant)
    
    /**
     * `now` stamps the extras config-LWW slot (docs/PHASE2.md).
     */
    fun `setExtraEnabled`(`extraId`: kotlin.String, `enabled`: kotlin.Boolean, `now`: LocalInstant)
    
    /**
     * Advances `context`'s pull cursor after applying a pull batch.
     *
     * `expected_reset_epoch` is the reset generation captured at the round-
     * trip's start; a stale advance (a `reset_all_data` ran since) NO-OPs and
     * returns `StaleReset`. This is the exact write the data-loss race turned
     * on: without the gate, a stale round-trip re-created `sync_state` with a
     * pre-reset `last_server_seq`, so later clean pulls (`server_seq > cursor`)
     * skipped the account's own re-pullable history forever (docs/PHASE2.md).
     */
    fun `setLastServerSeq`(`context`: kotlin.String, `seq`: kotlin.Long, `expectedResetEpoch`: kotlin.Long): SyncOutcome
    
    /**
     * Edit the challenge's start date after the fact — e.g. the user picked
     * the wrong "already underway" day at onboarding. Config-only, like the
     * other challenge setters: the projection re-indexes day numbers from the
     * new start automatically. Days that now fall before the new start are
     * simply outside the challenge; days newly uncovered by an earlier start
     * can be backfilled. `now` stamps the challenge config-LWW slot
     * (docs/PHASE2.md), so the edit syncs like any other config change.
     *
     * Contrast `day_cutoff_minutes`, which deliberately has NO setter — it
     * would move events to different DAYS. Changing the start date only
     * renumbers days; events keep the calendar dates they were logged on.
     */
    fun `setStartDate`(`startDate`: kotlin.String, `now`: LocalInstant)
    
    /**
     * The waking window only drives WaterState pacing and the
     * discourage_catch_up display — never day attribution or completion — so
     * editing it mid-challenge is a plain config update, not an event.
     */
    fun `setWakingWindow`(`startMinutes`: kotlin.UShort, `endMinutes`: kotlin.UShort, `now`: LocalInstant)
    
    /**
     * Goal changes are events: past days keep the goal they were lived under.
     */
    fun `setWaterGoal`(`ml`: kotlin.Long, `now`: LocalInstant)
    
    fun `shareCard`(`date`: kotlin.String, `now`: LocalInstant): ShareCardData
    
    fun `summary`(`now`: LocalInstant): ChallengeSummary
    
    fun `today`(`now`: LocalInstant): TodayState
    
    /**
     * `now` stamps the presets config-LWW slot (docs/PHASE2.md): presets are
     * config, not events, and sync last-writer-wins on this timestamp.
     */
    fun `updatePresets`(`presets`: List<ContainerPreset>, `now`: LocalInstant)
    
    /**
     * Every non-revoked `water_add` / `water_adjust` event attributed to
     * `date` (adds positive, corrections negative), ordered by `logged_at`
     * ascending. Attribution is exactly the day projection's (cutoff,
     * closed-day rollover, explicit effective_date), so the entries sum to
     * that date's raw signed total — `DayState.water_ml` folds the same
     * entries with a running floor at 0 and only diverges (reading higher,
     * never lower) after a revoke reorders history. `day_backfilled` water
     * is a flag with no quantity and is deliberately excluded.
     */
    fun `waterLog`(`date`: kotlin.String, `now`: LocalInstant): List<WaterLogEntry>
    
    fun `waterState`(`now`: LocalInstant): WaterState
    
    companion object
}

open class DromeStore: Disposable, AutoCloseable, DromeStoreInterface
{

    @Suppress("UNUSED_PARAMETER")
    /**
     * @suppress
     */
    constructor(withHandle: UniffiWithHandle, handle: Long) {
        this.handle = handle
        this.cleanable = UniffiLib.CLEANER.register(this, UniffiCleanAction(handle))
    }

    /**
     * @suppress
     *
     * This constructor can be used to instantiate a fake object. Only used for tests. Any
     * attempt to actually use an object constructed this way will fail as there is no
     * connected Rust object.
     */
    @Suppress("UNUSED_PARAMETER")
    constructor(noHandle: NoHandle) {
        this.handle = 0
        this.cleanable = null
    }

    protected val handle: Long
    protected val cleanable: UniffiCleaner.Cleanable?

    private val wasDestroyed = AtomicBoolean(false)
    private val callCounter = AtomicLong(1)

    /**
     * Whether the current object has been destroyed and its reference is gone in the Rust side.
     */
    val uniffiIsDestroyed: Boolean get() = wasDestroyed.get()

    override fun destroy() {
        // Only allow a single call to this method.
        // TODO: maybe we should log a warning if called more than once?
        if (this.wasDestroyed.compareAndSet(false, true)) {
            // This decrement always matches the initial count of 1 given at creation time.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    @Synchronized
    override fun close() {
        this.destroy()
    }

    internal inline fun <R> callWithHandle(block: (handle: Long) -> R): R {
        // Check and increment the call counter, to keep the object alive.
        // This needs a compare-and-set retry loop in case of concurrent updates.
        do {
            val c = this.callCounter.get()
            if (c == 0L) {
                throw IllegalStateException("${this.javaClass.simpleName} object has already been destroyed")
            }
            if (c == Long.MAX_VALUE) {
                throw IllegalStateException("${this.javaClass.simpleName} call counter would overflow")
            }
        } while (! this.callCounter.compareAndSet(c, c + 1L))
        // Now we can safely do the method call without the handle being freed concurrently.
        try {
            return block(this.uniffiCloneHandle())
        } finally {
            // This decrement always matches the increment we performed above.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    // Use a static inner class instead of a closure so as not to accidentally
    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val handle: Long) : Runnable {
        override fun run() {
            if (handle == 0.toLong()) {
                // Fake object created with `NoHandle`, don't try to free.
                return;
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_drome_core_fn_free_dromestore(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object");
        }
        return uniffiRustCall() { status ->
            UniffiLib.uniffi_drome_core_fn_clone_dromestore(handle, status)
        }
    }

    
    /**
     * Advances `context`'s push watermark past every acked uuid this store
     * holds (the new `synced_through` is the max of their local rowids, never
     * moving backwards). Unknown uuids are ignored.
     *
     * `expected_reset_epoch` is the reset generation the round-trip captured
     * at its start (from `current_reset_epoch`). If a `reset_all_data` ran
     * since, this is a stale in-flight write: it NO-OPs and returns
     * `StaleReset` (not an error), so a re-minted post-reset store's
     * watermark is never dragged forward by a round-trip the reset invalidated
     * (docs/PHASE2.md, sync/reset epoch invariant).
     */
    @Throws(DromeException::class)override fun `ackPushed`(`context`: kotlin.String, `uuids`: List<kotlin.String>, `expectedResetEpoch`: kotlin.Long): SyncOutcome {
            return FfiConverterTypeSyncOutcome.lift(
    callWithHandle {
    uniffiRustCallWithError(DromeException) { _status ->
    UniffiLib.uniffi_drome_core_fn_method_dromestore_ack_pushed(
        it,
        
        FfiConverterString.lower(`context`),
        FfiConverterSequenceString.lower(`uuids`),
        FfiConverterLong.lower(`expectedResetEpoch`),_status)
}
    }
    )
    }
    

    
    @Throws(DromeException::class)override fun `activeChallenge`(): Challenge? {
            return FfiConverterOptionalTypeChallenge.lift(
    callWithHandle {
    uniffiRustCallWithError(DromeException) { _status ->
    UniffiLib.uniffi_drome_core_fn_method_dromestore_active_challenge(
        it,
        _status)
}
    }
    )
    }
    

    
