/**
 * Crate-wide error type. Crossed to Swift as a flat error (variant + message).
 */
sealed class DromeException(message: String): kotlin.Exception(message) {
        
        class Database(message: String) : DromeException(message)
        
        class Serialization(message: String) : DromeException(message)
        
        class InvalidDate(message: String) : DromeException(message)
        
        class InvalidArgument(message: String) : DromeException(message)
        
        class NoActiveChallenge(message: String) : DromeException(message)
        
        class ActiveChallengeExists(message: String) : DromeException(message)
        
        class EventNotFound(message: String) : DromeException(message)
        
        class TaskNotRevocable(message: String) : DromeException(message)
        
        class UnknownExtra(message: String) : DromeException(message)
        
        class TimeOutOfRange(message: String) : DromeException(message)
        
        class Internal(message: String) : DromeException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<DromeException> {
        override fun lift(error_buf: RustBuffer.ByValue): DromeException = FfiConverterTypeDromeError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeDromeError : FfiConverterRustBuffer<DromeException> {
    override fun read(buf: ByteBuffer): DromeException {
        
            return when(buf.getInt()) {
            1 -> DromeException.Database(FfiConverterString.read(buf))
            2 -> DromeException.Serialization(FfiConverterString.read(buf))
            3 -> DromeException.InvalidDate(FfiConverterString.read(buf))
            4 -> DromeException.InvalidArgument(FfiConverterString.read(buf))
            5 -> DromeException.NoActiveChallenge(FfiConverterString.read(buf))
            6 -> DromeException.ActiveChallengeExists(FfiConverterString.read(buf))
            7 -> DromeException.EventNotFound(FfiConverterString.read(buf))
            8 -> DromeException.TaskNotRevocable(FfiConverterString.read(buf))
            9 -> DromeException.UnknownExtra(FfiConverterString.read(buf))
            10 -> DromeException.TimeOutOfRange(FfiConverterString.read(buf))
            11 -> DromeException.Internal(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: DromeException): ULong {
        return 4UL
    }

    override fun write(value: DromeException, buf: ByteBuffer) {
        when(value) {
            is DromeException.Database -> {
                buf.putInt(1)
                Unit
            }
            is DromeException.Serialization -> {
                buf.putInt(2)
                Unit
            }
            is DromeException.InvalidDate -> {
                buf.putInt(3)
                Unit
            }
            is DromeException.InvalidArgument -> {
                buf.putInt(4)
                Unit
            }
            is DromeException.NoActiveChallenge -> {
                buf.putInt(5)
                Unit
            }
            is DromeException.ActiveChallengeExists -> {
                buf.putInt(6)
                Unit
            }
            is DromeException.EventNotFound -> {
                buf.putInt(7)
                Unit
            }
            is DromeException.TaskNotRevocable -> {
                buf.putInt(8)
                Unit
            }
            is DromeException.UnknownExtra -> {
                buf.putInt(9)
                Unit
            }
            is DromeException.TimeOutOfRange -> {
                buf.putInt(10)
                Unit
            }
            is DromeException.Internal -> {
                buf.putInt(11)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * A core task `revoke_task` can un-complete. Workouts and water are
 * deliberately NOT here: they already revoke entry-by-entry
 * (`WorkoutEntry.event_uuid` / the `water_log` ledger + `revoke_event`).
 */
sealed class RevocableTask {
    
    object Diet : RevocableTask()
    
    
    object NoJunk : RevocableTask()
    
    
    object Photo : RevocableTask()
    
    
    object Reading : RevocableTask()
    
    
    data class Extra(
        val `id`: kotlin.String) : RevocableTask()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeRevocableTask : FfiConverterRustBuffer<RevocableTask>{
    override fun read(buf: ByteBuffer): RevocableTask {
        return when(buf.getInt()) {
            1 -> RevocableTask.Diet
            2 -> RevocableTask.NoJunk
            3 -> RevocableTask.Photo
            4 -> RevocableTask.Reading
            5 -> RevocableTask.Extra(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: RevocableTask): ULong = when(value) {
        is RevocableTask.Diet -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is RevocableTask.NoJunk -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is RevocableTask.Photo -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is RevocableTask.Reading -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is RevocableTask.Extra -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`id`)
            )
        }
    }

    override fun write(value: RevocableTask, buf: ByteBuffer) {
        when(value) {
            is RevocableTask.Diet -> {
                buf.putInt(1)
                Unit
            }
            is RevocableTask.NoJunk -> {
                buf.putInt(2)
                Unit
            }
            is RevocableTask.Photo -> {
                buf.putInt(3)
                Unit
            }
            is RevocableTask.Reading -> {
                buf.putInt(4)
                Unit
            }
            is RevocableTask.Extra -> {
                buf.putInt(5)
                FfiConverterString.write(value.`id`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






